// Add or update `url` on any of the 13 repos below to check its associated website
const repoTargets = [
  { id: 'main', label: 'Main Site (EDS)', url: 'https://emergingdefensesolutions.com', owner: 'afrodojo', repo: 'emerging-defense-solutions-update' },
  { id: 'defense', label: 'Defense Training Division', url: 'https://defense.eds-360.com', owner: 'afrodojo', repo: 'eds-defense-training-division' },
  { id: 'cyber', label: 'Cybersecurity Division', url: 'https://cyber.eds-360.com', owner: 'afrodojo', repo: 'eds-cybersecurity-division' },
  { id: 'nps', label: 'Notary & Process Server Division', url: 'https://nps.eds-360.com', owner: 'afrodojo', repo: 'eds-notary-process-server-division' },
  { id: 'hive', label: 'HIVE Platform', url: 'https://hive.eds-360.com', owner: 'afrodojo', repo: 'hive-eds-360' },
  { id: 'hive-align', label: 'HIVE Alignment', url: 'https://hive-align.eds-360.com', owner: 'afrodojo', repo: 'hive-alignment' },
  { id: 'cyberdojo-main', label: 'Cyber Dojo Sensei', url: 'https://cyberdojosensei.eds-360.com', owner: 'afrodojo', repo: 'cyberdojosensei' },
  { id: 'cyberdojo-alt', label: 'Cyber Dojo Sensei (Alt)', url: '', owner: 'afrodojo', repo: 'cyber-dojo-sensei' },
  { id: 'compliance-engine', label: 'EDS-360 Compliance Risk Engine', url: '', owner: 'EDSSensei2026', repo: 'eds-360-compliance-risk-engine' },
  { id: 'formal-rag', label: 'EDS Formal RAG', url: '', owner: 'afrodojo', repo: 'eds-formal-rag' },
  { id: 'izulu-sentinel', label: 'IzuluSentinel', url: '', owner: 'afrodojo', repo: 'IzuluSentinel' },
  { id: 'sensei-phd', label: 'Sensei PhD Research', url: '', owner: 'afrodojo', repo: 'sensei-phd' },
  { id: 'hybrid-das-sensei', label: 'AI Lab Hybrid DAS Sensei', url: '', owner: 'afrodojo', repo: 'AI-Lab-Hybrid-DASSensei' }
];

const ghToken = $env.GITHUB_TOKEN || '';
const headers = {
  'Accept': 'application/vnd.github+json',
  'User-Agent': 'EDS-360-Platform-Hub'
};
if (ghToken) headers['Authorization'] = `Bearer ${ghToken}`;

const items = [];
let failedCiCount = 0;
let openAlertsTotal = 0;
let healthyRepos = 0;
let linkedSitesChecked = 0;
let linkedSitesUp = 0;

for (const t of repoTargets) {
  let siteSummary = 'none-linked';
  let siteOk = true;

  if (t.url) {
    linkedSitesChecked += 1;
    const t0 = Date.now();
    let httpCode = 0;
    try {
      const ctrl = new AbortController();
      const timer = setTimeout(() => ctrl.abort(), 5000);
      const res = await fetch(t.url, { method: 'GET', redirect: 'follow', signal: ctrl.signal });
      clearTimeout(timer);
      httpCode = res.status;
      siteOk = (res.status >= 200 && res.status < 400) || (t.id === 'hive' && res.status === 403);
    } catch (_) {
      httpCode = 0;
      siteOk = false;
    }
    const ms = Date.now() - t0;
    if (siteOk) linkedSitesUp += 1;
    siteSummary = siteOk
      ? (httpCode === 403 ? `${t.url} -> HTTP 403 (WAF/Auth) [${ms}ms]` : `${t.url} -> HTTP ${httpCode} [${ms}ms]`)
      : `${t.url} -> DOWN (${httpCode || 'ERR'}) [${ms}ms]`;
  }

  let branch = 'main';
  let latestSha = 'n/a';
  let latestMsg = 'no commit data';
  let ciState = 'n/a';
  let alertSummary = 'alerts:n/a';
  let repoOk = false;

  try {
    const repoRes = await fetch(`https://api.github.com/repos/${t.owner}/${t.repo}`, { headers });
    if (repoRes.ok) {
      const repoData = await repoRes.json();
      branch = repoData.default_branch || 'main';
    }

    const commitsRes = await fetch(`https://api.github.com/repos/${t.owner}/${t.repo}/commits/${branch}?per_page=1`, { headers });
    if (commitsRes.ok) {
      const commits = await commitsRes.json();
      const c = Array.isArray(commits) ? commits[0] : null;
      if (c) {
        repoOk = true;
        latestSha = (c.sha || '').slice(0, 7);
        latestMsg = ((c.commit?.message || '').split('\n')[0] || 'commit').slice(0, 60);
      }
    } else if (commitsRes.status === 404 || commitsRes.status === 409) {
      latestMsg = `repo/branch status ${commitsRes.status} (private or empty)`;
    } else if (commitsRes.status === 403) {
      latestMsg = 'rate-limited or private (set GITHUB_TOKEN)';
    }

    const runsRes = await fetch(`https://api.github.com/repos/${t.owner}/${t.repo}/actions/runs?branch=${branch}&per_page=1`, { headers });
    if (runsRes.ok) {
      const runsData = await runsRes.json();
      const run = Array.isArray(runsData.workflow_runs) ? runsData.workflow_runs[0] : null;
      if (run) {
        ciState = run.conclusion || run.status || 'unknown';
        if (ciState === 'failure' || ciState === 'cancelled' || ciState === 'timed_out') {
          failedCiCount += 1;
          repoOk = false;
        }
      } else {
        ciState = 'no-runs';
      }
    }

    const alertsRes = await fetch(`https://api.github.com/repos/${t.owner}/${t.repo}/dependabot/alerts?state=open&per_page=100`, { headers });
    if (alertsRes.ok) {
      const alertsList = await alertsRes.json();
      const count = Array.isArray(alertsList) ? alertsList.length : 0;
      openAlertsTotal += count;
      alertSummary = `open-alerts:${count}`;
      if (count > 0) repoOk = false;
    } else {
      alertSummary = 'alerts:scope-restricted';
    }
  } catch (err) {
    latestMsg = `err: ${err.message || 'fetch failed'}`.slice(0, 60);
  }

  if (repoOk) healthyRepos += 1;

  items.push({
    ref: `REPO-${t.id.toUpperCase()}`,
    owner: 'Eng & Platform',
    detail: `${t.label} [${t.owner}/${t.repo}@${latestSha}] (${latestMsg}) | CI:${ciState} | ${alertSummary} | Site:${siteSummary} (CM.L2-3.4.1 / SI.L2-3.14.1)`,
    status: siteOk && (repoOk || ciState === 'no-runs') ? 'compliant' : 'needs_review'
  });
}

const nowTime = new Date().toISOString().slice(11, 19) + 'Z';

return [{
  json: {
    tenantId: 'eds-360',
    scope: 'it',
    key: 'devops',
    sourceLabel: 'n8n-github-13repos-linked-sites',
    kpis: [
      { label: 'Repos Monitored', value: `${healthyRepos} / ${repoTargets.length}`, sub: `Synced ${nowTime}`, accent: 'text-cyan-300' },
      { label: 'Linked Sites Up', value: `${linkedSitesUp} / ${linkedSitesChecked}`, sub: 'Repo-associated endpoints', accent: linkedSitesUp === linkedSitesChecked ? 'text-emerald-300' : 'text-amber-300' },
      { label: 'CI Failures', value: `${failedCiCount}`, sub: 'Across 13 repos', accent: failedCiCount === 0 ? 'text-emerald-300' : 'text-rose-300' },
      { label: 'Open Alerts', value: `${openAlertsTotal}`, sub: 'Dependabot / supply-chain', accent: openAlertsTotal === 0 ? 'text-indigo-300' : 'text-amber-300' }
    ],
    items
  }
}];
